cat > src/params.rs <<'EOF'
//! Typed access to the members of a request object. A `null` member counts as absent.

use std::ops::RangeInclusive;

use serde_json::{Map, Value};

use crate::error::{Error, ErrorCode, Result};

pub struct Params<'a>(&'a Map<String, Value>);

impl<'a> Params<'a> {
    pub fn new(members: &'a Map<String, Value>) -> Self {
        Self(members)
    }

    pub fn members(&self) -> &'a Map<String, Value> {
        self.0
    }

    pub fn get(&self, name: &str) -> Option<&'a Value> {
        self.0.get(name).filter(|v| !v.is_null())
    }

    pub fn is_present(&self, name: &str) -> bool {
        self.get(name).is_some()
    }

    /// Fails with `MissingParameter` for the first absent name; call before any value check.
    pub fn require(&self, names: &[&str]) -> Result<()> {
        match names.iter().find(|n| !self.is_present(n)) {
            Some(name) => Err(missing(name)),
            None => Ok(()),
        }
    }

    pub fn string(&self, name: &str) -> Result<Option<&'a str>> {
        self.get(name)
            .map(|v| v.as_str().ok_or_else(|| invalid(name, "must be a string")))
            .transpose()
    }

    pub fn required_string(&self, name: &str) -> Result<&'a str> {
        self.string(name)?.ok_or_else(|| missing(name))
    }

    pub fn boolean(&self, name: &str) -> Result<Option<bool>> {
        self.get(name)
            .map(|v| v.as_bool().ok_or_else(|| invalid(name, "must be a boolean")))
            .transpose()
    }

    pub fn integer(&self, name: &str, range: RangeInclusive<u32>) -> Result<Option<u32>> {
        self.get(name)
            .map(|v| {
                v.as_u64()
                    .and_then(|n| u32::try_from(n).ok())
                    .filter(|n| range.contains(n))
                    .ok_or_else(|| {
                        invalid(
                            name,
                            format!("must be an integer from {} to {}", range.start(), range.end()),
                        )
                    })
            })
            .transpose()
    }

    pub fn required_integer(&self, name: &str, range: RangeInclusive<u32>) -> Result<u32> {
        self.integer(name, range)?.ok_or_else(|| missing(name))
    }

    /// An identifier of 1 to 128 characters from `A-Z a-z 0-9 _ -`.
    pub fn identifier(&self, name: &str) -> Result<Option<&'a str>> {
        let Some(s) = self.string(name)? else { return Ok(None) };
        if (1..=128).contains(&s.len()) && s.bytes().all(is_name_byte) {
            Ok(Some(s))
        } else {
            Err(invalid(name, "must be 1 to 128 characters from A-Z a-z 0-9 _ -"))
        }
    }
}

pub fn is_name_byte(b: u8) -> bool {
    b.is_ascii_alphanumeric() || b == b'_' || b == b'-'
}

pub fn missing(name: &str) -> Error {
    Error::new(ErrorCode::MissingParameter, format!("{name} is required"))
}

pub fn invalid(name: &str, why: impl std::fmt::Display) -> Error {
    Error::new(ErrorCode::InvalidParameterValue, format!("{name} {why}"))
}
