cat > src/attrs.rs <<'EOF'
//! Queue attributes (SPEC section 4) and the partial updates that `CreateQueue` and
//! `SetQueueAttributes` carry.

use crate::error::{Error, ErrorCode, Result};
use crate::params::{invalid, Params};

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DeadLetter {
    pub queue: String,
    pub max_receive_count: u32,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Attributes {
    pub visibility_timeout: u32,
    pub delay_seconds: u32,
    pub retention_seconds: u32,
    pub fifo: bool,
    pub content_based_deduplication: bool,
    pub dead_letter: Option<DeadLetter>,
}

impl Default for Attributes {
    fn default() -> Self {
        Self {
            visibility_timeout: 30,
            delay_seconds: 0,
            retention_seconds: 345_600,
            fifo: false,
            content_based_deduplication: false,
            dead_letter: None,
        }
    }
}

/// The attributes present in a request's `Attributes` object.
#[derive(Debug, Default)]
pub struct AttributeUpdate {
    pub visibility_timeout: Option<u32>,
    pub delay_seconds: Option<u32>,
    pub retention_seconds: Option<u32>,
    pub fifo: Option<bool>,
    pub content_based_deduplication: Option<bool>,
    pub dead_letter_queue: Option<String>,
    pub max_receive_count: Option<u32>,
}

impl AttributeUpdate {
    /// Reads and validates the `Attributes` member; an absent member is an empty update.
    pub fn parse(params: &Params) -> Result<Self> {
        let Some(value) = params.get("Attributes") else { return Ok(Self::default()) };
        let members = value.as_object().ok_or_else(|| invalid("Attributes", "must be an object"))?;
        if let Some(name) = members.keys().find(|k| !ATTRIBUTE_NAMES.contains(&k.as_str())) {
            return Err(invalid("Attributes", format!("has unknown attribute {name}")));
        }
        let p = Params::new(members);
        Ok(Self {
            visibility_timeout: p.integer("VisibilityTimeout", 0..=43_200)?,
            delay_seconds: p.integer("DelaySeconds", 0..=900)?,
            retention_seconds: p.integer("RetentionSeconds", 60..=1_209_600)?,
            fifo: p.boolean("Fifo")?,
            content_based_deduplication: p.boolean("ContentBasedDeduplication")?,
            dead_letter_queue: p.string("DeadLetterQueue")?.map(str::to_owned),
            max_receive_count: p.integer("MaxReceiveCount", 1..=1000)?,
        })
    }

    /// `DeadLetterQueue` and `MaxReceiveCount` must come together.
    pub fn check_dead_letter_pair(&self) -> Result<()> {
        if self.dead_letter_queue.is_some() != self.max_receive_count.is_some() {
            return Err(Error::new(
                ErrorCode::InvalidParameterValue,
                "DeadLetterQueue and MaxReceiveCount must be given together",
            ));
        }
        Ok(())
    }

    /// The dead-letter configuration of this update, if it carries one.
    pub fn dead_letter(&self) -> Option<DeadLetter> {
        match (&self.dead_letter_queue, self.max_receive_count) {
            (Some(queue), Some(max_receive_count)) => {
                Some(DeadLetter { queue: queue.clone(), max_receive_count })
            }
            _ => None,
        }
    }

    /// `base` with every attribute of this update replaced. Assumes the pair check passed.
    pub fn apply_to(&self, base: &Attributes) -> Attributes {
        Attributes {
            visibility_timeout: self.visibility_timeout.unwrap_or(base.visibility_timeout),
            delay_seconds: self.delay_seconds.unwrap_or(base.delay_seconds),
            retention_seconds: self.retention_seconds.unwrap_or(base.retention_seconds),
            fifo: self.fifo.unwrap_or(base.fifo),
            content_based_deduplication: self
                .content_based_deduplication
                .unwrap_or(base.content_based_deduplication),
            dead_letter: self.dead_letter().or_else(|| base.dead_letter.clone()),
        }
    }
}

const ATTRIBUTE_NAMES: [&str; 7] = [
    "VisibilityTimeout",
    "DelaySeconds",
    "RetentionSeconds",
    "Fifo",
    "ContentBasedDeduplication",
    "DeadLetterQueue",
    "MaxReceiveCount",
];
EOF
