cat > src/queue.rs <<'EOF'
//! One queue: its attributes, its messages in arrival order and its deduplication record.

use std::collections::{BTreeMap, HashMap, HashSet};

use crate::attrs::Attributes;

const DEDUP_WINDOW: u64 = 300;

#[derive(Debug, Clone)]
pub struct Message {
    pub id: u64,
    pub body: String,
    pub sent_at: u64,
    pub receive_count: u32,
    pub first_received_at: Option<u64>,
    pub group: Option<String>,
    pub sequence: Option<u64>,
    /// Latest receipt handle issued for this message.
    pub receipt: Option<u64>,
    delayed_until: u64,
    in_flight_until: u64,
}

#[derive(Debug, PartialEq, Eq)]
enum State {
    Delayed,
    InFlight,
    Visible,
}

impl Message {
    fn state(&self, now: u64) -> State {
        if now < self.delayed_until {
            State::Delayed
        } else if now < self.in_flight_until {
            State::InFlight
        } else {
            State::Visible
        }
    }
}

#[derive(Debug, Default, PartialEq, Eq)]
pub struct Counts {
    pub visible: usize,
    pub in_flight: usize,
    pub delayed: usize,
}

/// Identity of an accepted (or deduplicated) FIFO or standard send.
#[derive(Debug, Clone, Copy)]
pub struct Accepted {
    pub message_id: u64,
    pub sequence: Option<u64>,
}

pub struct NewMessage {
    pub id: u64,
    pub body: String,
    pub group: Option<String>,
    pub delay: u32,
    pub dedup_id: Option<String>,
}

pub struct Received {
    pub delivered: Vec<Message>,
    /// Messages that exceeded `MaxReceiveCount`, removed from this queue and awaiting the
    /// dead-letter queue.
    pub dead: Vec<Message>,
}

pub struct Queue {
    pub attrs: Attributes,
    /// Keyed by arrival number, so iteration is arrival order and removal is cheap.
    messages: BTreeMap<u64, Message>,
    next_arrival: u64,
    by_receipt: HashMap<u64, u64>,
    next_sequence: u64,
    /// Lower bound of `sent_at` over `messages`; lets `expire` skip the scan.
    oldest_sent_at: u64,
    dedup: HashMap<String, (u64, Accepted)>,
}

impl Queue {
    pub fn new(attrs: Attributes) -> Self {
        Self {
            attrs,
            messages: BTreeMap::new(),
            next_arrival: 0,
            by_receipt: HashMap::new(),
            next_sequence: 1,
            oldest_sent_at: u64::MAX,
            dedup: HashMap::new(),
        }
    }

    pub fn len(&self) -> usize {
        self.messages.len()
    }

    /// Removes messages past retention. Must run before anything reads the queue.
    pub fn expire(&mut self, now: u64) {
        let retention = u64::from(self.attrs.retention_seconds);
        if self.oldest_sent_at.saturating_add(retention) > now {
            return;
        }
        self.messages.retain(|_, m| now < m.sent_at + retention);
        let messages = &self.messages;
        self.by_receipt.retain(|_, key| messages.contains_key(key));
        self.oldest_sent_at = self.messages.values().map(|m| m.sent_at).min().unwrap_or(u64::MAX);
    }

    pub fn counts(&self, now: u64) -> Counts {
        let mut counts = Counts::default();
        for m in self.messages.values() {
            match m.state(now) {
                State::Visible => counts.visible += 1,
                State::InFlight => counts.in_flight += 1,
                State::Delayed => counts.delayed += 1,
            }
        }
        counts
    }

    pub fn purge(&mut self) {
        self.messages.clear();
        self.by_receipt.clear();
        self.oldest_sent_at = u64::MAX;
    }

    /// The original message of a send that repeats a deduplication id inside the window.
    pub fn duplicate_of(&self, dedup_id: &str, now: u64) -> Option<Accepted> {
        self.dedup
            .get(dedup_id)
            .filter(|(at, _)| now - at < DEDUP_WINDOW)
            .map(|(_, accepted)| *accepted)
    }

    pub fn add(&mut self, new: NewMessage, now: u64) -> Accepted {
        let sequence = self.take_sequence();
        let accepted = Accepted { message_id: new.id, sequence };
        if let Some(dedup_id) = new.dedup_id {
            self.dedup.insert(dedup_id, (now, accepted));
        }
        self.insert(Message {
            id: new.id,
            body: new.body,
            sent_at: now,
            receive_count: 0,
            first_received_at: None,
            group: new.group,
            sequence,
            receipt: None,
            delayed_until: now + u64::from(new.delay),
            in_flight_until: 0,
        });
        accepted
    }

    /// Takes in a message dead-lettered from another queue.
    pub fn add_dead_letter(&mut self, mut message: Message) {
        message.receive_count = 0;
        message.first_received_at = None;
        message.receipt = None;
        message.delayed_until = 0;
        message.in_flight_until = 0;
        message.sequence = self.take_sequence();
        self.insert(message);
    }

    fn take_sequence(&mut self) -> Option<u64> {
        self.attrs.fifo.then(|| {
            let n = self.next_sequence;
            self.next_sequence += 1;
            n
        })
    }

    fn insert(&mut self, message: Message) {
        self.oldest_sent_at = self.oldest_sent_at.min(message.sent_at);
        self.messages.insert(self.next_arrival, message);
        self.next_arrival += 1;
    }

    /// Delivers up to `max` eligible messages, drawing handle numbers from `last_handle`.
    pub fn receive(&mut self, now: u64, max: usize, visibility: u32, last_handle: &mut u64) -> Received {
        let max_receive_count = self.attrs.dead_letter.as_ref().map(|d| d.max_receive_count);
        let fifo = self.attrs.fifo;
        let mut seen_groups: HashSet<String> = HashSet::new();
        let mut dead_keys = Vec::new();
        let mut delivered = Vec::new();

        for (&key, message) in self.messages.iter_mut() {
            if fifo {
                let Some(group) = &message.group else { continue };
                if seen_groups.contains(group) {
                    continue;
                }
                if message.state(now) != State::Visible {
                    seen_groups.insert(group.clone());
                    continue;
                }
            } else if message.state(now) != State::Visible {
                continue;
            }
