        let queue = self.queues.get_mut(name).ok_or_else(|| no_such_queue(name))?;
        queue.expire(now);
        Ok(queue)
    }

    fn create_queue(&mut self, p: &Params) -> Result<Response> {
        p.require(&["QueueName"])?;
        let name = p.required_string("QueueName")?;
        validate_queue_name(name)?;
        let update = AttributeUpdate::parse(p)?;
        let attrs = update.apply_to(&Attributes::default());
        if name.ends_with(".fifo") != attrs.fifo {
            return Err(Error::new(
                ErrorCode::QueueNameInvalid,
                "the .fifo suffix and Fifo=true must go together",
            ));
        }
        if attrs.content_based_deduplication && !attrs.fifo {
            return Err(invalid("ContentBasedDeduplication", "requires a FIFO queue"));
        }
        update.check_dead_letter_pair()?;
        if let Some(existing) = self.queues.get(name) {
            return if existing.attrs == attrs {
                Ok(Response::new())
            } else {
                Err(Error::new(ErrorCode::QueueAlreadyExists, format!("{name} exists with other attributes")))
            };
        }
        if let Some(dead_letter) = &attrs.dead_letter {
            let dlq = self.queues.get(&dead_letter.queue).ok_or_else(|| no_such_queue(&dead_letter.queue))?;
            if dlq.attrs.fifo != attrs.fifo {
                return Err(invalid("DeadLetterQueue", "must be of the same type as the queue"));
            }
        }
        if self.queues.len() >= MAX_QUEUES {
            return Err(Error::new(ErrorCode::LimitExceeded, "too many queues"));
        }
        self.queues.insert(name.to_owned(), Queue::new(attrs));
        Ok(Response::new())
    }

    fn set_queue_attributes(&mut self, p: &Params) -> Result<Response> {
        p.require(&["QueueName", "Attributes"])?;
        let name = p.required_string("QueueName")?;
        let update = AttributeUpdate::parse(p)?;
        let queue = self.queue_mut(name)?;
        let fifo = queue.attrs.fifo;
        if update.fifo.is_some() {
            return Err(Error::new(ErrorCode::UnsupportedOperation, "the type of a queue cannot change"));
        }
        if update.content_based_deduplication == Some(true) && !fifo {
            return Err(invalid("ContentBasedDeduplication", "requires a FIFO queue"));
        }
        update.check_dead_letter_pair()?;
        if let Some(dead_letter) = update.dead_letter() {
            let dlq = self.queues.get(&dead_letter.queue).ok_or_else(|| no_such_queue(&dead_letter.queue))?;
            if dead_letter.queue == name || dlq.attrs.fifo != fifo {
                return Err(invalid("DeadLetterQueue", "must be another queue of the same type"));
            }
        }
        let queue = self.queue_mut(name)?;
        queue.attrs = update.apply_to(&queue.attrs);
        Ok(Response::new())
    }

    fn get_queue_attributes(&mut self, p: &Params) -> Result<Response> {
        p.require(&["QueueName"])?;
        let name = p.required_string("QueueName")?;
        let now = self.now;
        let queue = self.queue_mut(name)?;
        let a = &queue.attrs;
        let mut attributes = json!({
            "VisibilityTimeout": a.visibility_timeout,
            "DelaySeconds": a.delay_seconds,
            "RetentionSeconds": a.retention_seconds,
            "Fifo": a.fifo,
            "ContentBasedDeduplication": a.content_based_deduplication,
        });
        if let Some(d) = &a.dead_letter {
            attributes["DeadLetterQueue"] = json!(d.queue);
            attributes["MaxReceiveCount"] = json!(d.max_receive_count);
        }
        let c = queue.counts(now);
        Ok(object(json!({
            "Attributes": attributes,
            "Counts": {"Visible": c.visible, "InFlight": c.in_flight, "Delayed": c.delayed},
        })))
    }

    fn list_queues(&mut self, p: &Params) -> Result<Response> {
        let prefix = p.string("Prefix")?.unwrap_or("");
        let names: Vec<&String> = self.queues.keys().filter(|n| n.starts_with(prefix)).collect();
        Ok(object(json!({ "QueueNames": names })))
    }

    fn delete_queue(&mut self, p: &Params) -> Result<Response> {
        p.require(&["QueueName"])?;
        let name = p.required_string("QueueName")?;
        self.queue_mut(name)?;
        self.queues.remove(name);
        for queue in self.queues.values_mut() {
            if queue.attrs.dead_letter.as_ref().is_some_and(|d| d.queue == name) {
                queue.attrs.dead_letter = None;
            }
        }
        Ok(Response::new())
    }

    fn purge_queue(&mut self, p: &Params) -> Result<Response> {
        p.require(&["QueueName"])?;
        self.queue_mut(p.required_string("QueueName")?)?.purge();
        Ok(Response::new())
    }

    fn tick(&mut self, p: &Params) -> Result<Response> {
        p.require(&["Seconds"])?;
        self.now += u64::from(p.required_integer("Seconds", 0..=1_209_600)?);
        Ok(object(json!({ "Now": self.now })))
    }

    fn send_message(&mut self, p: &Params) -> Result<Response> {
        p.require(&["QueueName", "Body"])?;
        let name = p.required_string("QueueName")?;
        let body = p.required_string("Body")?;
        if !(1..=1024).contains(&body.len()) {
            return Err(invalid("Body", "must be 1 to 1024 bytes"));
        }
        let delay = p.integer("DelaySeconds", 0..=900)?;
        let group = p.identifier("GroupId")?;
        let dedup_id = p.identifier("DeduplicationId")?;

        let now = self.now;
        let id = self.last_message_id + 1;
        let queue = self.queue_mut(name)?;
        let fifo = queue.attrs.fifo;
        if (!fifo && (group.is_some() || dedup_id.is_some())) || (fifo && delay.is_some()) {
            return Err(Error::new(
                ErrorCode::UnsupportedOperation,
                "GroupId and DeduplicationId need a FIFO queue; DelaySeconds needs a standard queue",
            ));
        }
        let mut dedup_key = None;
        if fifo {
            if group.is_none() {
                return Err(crate::params::missing("GroupId"));
            }
            let key = match dedup_id {
                Some(id) => id,
                None if queue.attrs.content_based_deduplication => body,
                None => return Err(crate::params::missing("DeduplicationId")),
            };
            if let Some(original) = queue.duplicate_of(key, now) {
                return Ok(send_result(original.message_id, original.sequence));
            }
            dedup_key = Some(key.to_owned());
        }
        if queue.len() >= MAX_MESSAGES_PER_QUEUE {
            return Err(Error::new(ErrorCode::LimitExceeded, "queue holds too many messages"));
        }
        let accepted = queue.add(
            NewMessage {
                id,
                body: body.to_owned(),
                group: group.map(str::to_owned),
                delay: delay.unwrap_or(queue.attrs.delay_seconds),
                dedup_id: dedup_key,
            },
            now,
        );
        self.last_message_id = id;
        Ok(send_result(accepted.message_id, accepted.sequence))
    }

    fn receive_message(&mut self, p: &Params) -> Result<Response> {
        p.require(&["QueueName"])?;
        let name = p.required_string("QueueName")?;
        let max = p.integer("MaxMessages", 1..=10)?.unwrap_or(1);
        let visibility = p.integer("VisibilityTimeout", 0..=43_200)?;

        let now = self.now;
        let mut last_handle = self.last_receipt_handle;
        let queue = self.queue_mut(name)?;
        let visibility = visibility.unwrap_or(queue.attrs.visibility_timeout);
        let dlq_name = queue.attrs.dead_letter.as_ref().map(|d| d.queue.clone());
        let received = queue.receive(now, max as usize, visibility, &mut last_handle);
        self.last_receipt_handle = last_handle;

        if !received.dead.is_empty() {
            let dlq_name = dlq_name.expect("messages are only dead-lettered when a dead-letter queue is set");
            let dlq = self.queue_mut(&dlq_name).expect("deleting a queue clears dead-letter references to it");
            for message in received.dead {
                dlq.add_dead_letter(message);
            }
        }
        let messages: Vec<Value> = received.delivered.iter().map(delivery_json).collect();
        Ok(object(json!({ "Messages": messages })))
    }

    fn delete_message(&mut self, p: &Params) -> Result<Response> {
        let (name, handle) = self.handle_params(p)?;
        let now = self.now;
        let queue = self.queue_mut(name)?;
        let key = self.live_handle(name, handle, now)?;
        self.queue_mut(name)?.remove(key);
        Ok(Response::new())
    }

    fn change_message_visibility(&mut self, p: &Params) -> Result<Response> {
        p.require(&["QueueName", "ReceiptHandle", "VisibilityTimeout"])?;
        let timeout = p.required_integer("VisibilityTimeout", 0..=43_200)?;
        let (name, handle) = self.handle_params(p)?;
        let now = self.now;
        let key = self.live_handle(name, handle, now)?;
        self.queue_mut(name)?.set_in_flight_until(key, now + u64::from(timeout));
        Ok(Response::new())
    }

    /// Shared parameter handling of `DeleteMessage` and `ChangeMessageVisibility`.
    fn handle_params<'a>(&self, p: &Params<'a>) -> Result<(&'a str, &'a str)> {
        p.require(&["QueueName", "ReceiptHandle"])?;
        Ok((p.required_string("QueueName")?, p.required_string("ReceiptHandle")?))
    }
}
