use miniq::Broker;
use serde_json::{json, Value};

fn run(broker: &mut Broker, line: &str) -> Value {
    serde_json::from_str(&broker.handle_line(line.as_bytes())).unwrap()
}

fn code(v: &Value) -> &str {
    assert_eq!(v["ok"], false, "{v}");
    v["error"]["code"].as_str().unwrap()
}

#[test]
fn malformed_lines_are_invalid_requests() {
    let mut b = Broker::new();
    for line in ["", "[]", "{", r#"{"Command": 1}"#, r#"{"Command": "Nope"}"#] {
        assert_eq!(code(&run(&mut b, line)), "InvalidRequest", "{line}");
    }
    assert_eq!(code(&serde_json::from_str(&b.handle_line(b"\xff")).unwrap()), "InvalidRequest");
}

#[test]
fn create_is_idempotent_only_for_equal_attributes() {
    let mut b = Broker::new();
    let create = r#"{"Command":"CreateQueue","QueueName":"jobs"}"#;
    assert_eq!(run(&mut b, create), json!({"ok": true}));
    assert_eq!(run(&mut b, create), json!({"ok": true}));
    let other = r#"{"Command":"CreateQueue","QueueName":"jobs","Attributes":{"DelaySeconds":5}}"#;
    assert_eq!(code(&run(&mut b, other)), "QueueAlreadyExists");
    let bad = r#"{"Command":"CreateQueue","QueueName":"a.b"}"#;
    assert_eq!(code(&run(&mut b, bad)), "QueueNameInvalid");
}

#[test]
fn receive_hides_message_until_visibility_timeout_ends() {
    let mut b = Broker::new();
    run(&mut b, r#"{"Command":"CreateQueue","QueueName":"q"}"#);
    let sent = run(&mut b, r#"{"Command":"SendMessage","QueueName":"q","Body":"hi"}"#);
    assert_eq!(sent, json!({"ok": true, "MessageId": "m-1"}));
    let got = run(&mut b, r#"{"Command":"ReceiveMessage","QueueName":"q"}"#);
    assert_eq!(
        got["Messages"],
        json!([{"MessageId":"m-1","ReceiptHandle":"r-1","Body":"hi","ReceiveCount":1,"SentAt":0,"FirstReceivedAt":0}])
    );
    let again = run(&mut b, r#"{"Command":"ReceiveMessage","QueueName":"q"}"#);
    assert_eq!(again["Messages"], json!([]));
    run(&mut b, r#"{"Command":"Tick","Seconds":30}"#);
    let later = run(&mut b, r#"{"Command":"ReceiveMessage","QueueName":"q"}"#);
    assert_eq!(later["Messages"][0]["ReceiveCount"], 2);
    assert_eq!(later["Messages"][0]["ReceiptHandle"], "r-2");
}

#[test]
fn receipt_handles_are_checked_in_order() {
    let mut b = Broker::new();
    run(&mut b, r#"{"Command":"CreateQueue","QueueName":"q"}"#);
    run(&mut b, r#"{"Command":"SendMessage","QueueName":"q","Body":"x"}"#);
    run(&mut b, r#"{"Command":"ReceiveMessage","QueueName":"q"}"#);
    let del = |h: &str| format!(r#"{{"Command":"DeleteMessage","QueueName":"q","ReceiptHandle":"{h}"}}"#);
    for h in ["r-01", "R-1", "r-1 ", "r-2"] {
        assert_eq!(code(&run(&mut b, &del(h))), "ReceiptHandleInvalid", "{h}");
    }
    assert_eq!(run(&mut b, &del("r-1")), json!({"ok": true}));
    assert_eq!(code(&run(&mut b, &del("r-1"))), "ReceiptHandleExpired");
}

#[test]
fn fifo_deduplicates_and_delivers_one_message_per_group() {
    let mut b = Broker::new();
    run(&mut b, r#"{"Command":"CreateQueue","QueueName":"q.fifo","Attributes":{"Fifo":true}}"#);
    let send = |body: &str| {
        format!(r#"{{"Command":"SendMessage","QueueName":"q.fifo","Body":"{body}","GroupId":"g","DeduplicationId":"d{body}"}}"#)
    };
    assert_eq!(run(&mut b, &send("a")), json!({"ok": true, "MessageId": "m-1", "SequenceNumber": 1}));
    assert_eq!(run(&mut b, &send("a")), json!({"ok": true, "MessageId": "m-1", "SequenceNumber": 1}));
    assert_eq!(run(&mut b, &send("b"))["MessageId"], "m-2");
    let got = run(&mut b, r#"{"Command":"ReceiveMessage","QueueName":"q.fifo","MaxMessages":10}"#);
    assert_eq!(got["Messages"].as_array().unwrap().len(), 1);
    run(&mut b, r#"{"Command":"Tick","Seconds":300}"#);
    assert_eq!(run(&mut b, &send("a"))["MessageId"], "m-3");
}

#[test]
fn exceeding_max_receive_count_moves_message_to_dead_letter_queue() {
    let mut b = Broker::new();
    run(&mut b, r#"{"Command":"CreateQueue","QueueName":"dead"}"#);
    run(&mut b, r#"{"Command":"CreateQueue","QueueName":"q","Attributes":{"VisibilityTimeout":0,"DeadLetterQueue":"dead","MaxReceiveCount":1}}"#);
    run(&mut b, r#"{"Command":"SendMessage","QueueName":"q","Body":"x"}"#);
    run(&mut b, r#"{"Command":"ReceiveMessage","QueueName":"q"}"#);
    let second = run(&mut b, r#"{"Command":"ReceiveMessage","QueueName":"q"}"#);
    assert_eq!(second["Messages"], json!([]));
    let moved = run(&mut b, r#"{"Command":"ReceiveMessage","QueueName":"dead"}"#);
    assert_eq!(moved["Messages"][0]["MessageId"], "m-1");
    assert_eq!(moved["Messages"][0]["ReceiveCount"], 1);
}

#[test]
fn retention_removes_messages_and_queue_limit_is_enforced() {
